            { "PrivatePositionMarkersHelp", "Також передає групі до 128 збережених точок і позначок смерті. Позначки друзів показують власника, доступні для навігації та залишаються тут тимчасовими, лише для читання." },
            { "PrivatePositionRouterManual", "Автоперенаправлення недоступне або термін сплив. Перенаправте TCP-порт на цей ПК вручну. Визначення IP й налаштування брандмауера не гарантують доступ з інтернету." },
            { "PrivatePositionFirewallFailed", "Не вдалося додати або перевірити правило Windows. Дозвольте застосунок і TCP-порт вручну; керована політика може забороняти зміни." },
            { "PrivatePositionFirewallReady", "Правило брандмауера Windows для застосунку й TCP-порту перевірено." },
            { "PrivatePositionLocalAddresses", "Адаптери LAN / VPN / віртуальні" },
            { "PrivatePositionPublicIpFailed", "Публічний IP не визначено. Увімкніть NAT-PMP або UPnP на роутері, повторіть або введіть публічний WAN IPv4. Для CGNAT попросіть публічний IP у провайдера." },
            { "PrivatePositionPublicIpHelp", "Одноранговий зв’язок без облікових записів і зовнішніх сервісів. Визначає публічний IPv4 локального роутера через NAT-PMP або UPnP. Хост запитує тимчасове перенаправлення NAT-PMP і правило Windows для застосунку й TCP-порту." },
