            { "WzOvDesc4", "Має вбудовану функцію A* для визначення маршруту руху через мережу доріг SCUM, обчислення маршрутів руху та відстані, що залишилася, у мілісекундах." },
            { "WzKeyMTitle", "Ключ карти SCUM" },
            { "WzKeyMDesc", "Відкрийте повну карту за допомогою налаштованого ключа карти. Використовуйте коліщатко для масштабування, перетягуйте для панорамування та клацайте правою кнопкою миші для параметрів маршрутної точки. Закрийте за допомогою клавіші карти або Esc." },
            { "WzKeyHomeTitle", "Налаштування" },
            { "WzKeyHomeDesc", "Відкрийте панель конфігурації, щоб налаштувати непрозорість, розмір, лінії сітки, фільтри категорій POI і спеціальні ігрові прив’язки клавіш." },
            { "WzKeyInsertTitle", "Додати маршрутну точку" },
            { "WzKeyInsertDesc", "Збережіть своє поточне положення як маршрутну точку з назвою для цієї карти." },
            { "WzKeyDeleteTitle", "Пошук" },
            { "WzKeyDeleteDesc", "Відкрийте каталог пошуку маршрутних точок, щоб швидко знаходити заправні станції, бункери, міста та розраховувати маршрути доріг." },
            { "WzKeyEndTitle", "Показати/сховати карту" },
            { "WzKeyEndDesc", "Миттєво вмикайте/вимикайте накладання мінікарти, не перериваючи синхронізацію фонових координат." },
            { "WzKeyCopyTitle", "Ручна синхронізація координат" },
            { "WzKeyCopyDesc", "Вручну запустіть отримання координат буфера обміну, якщо автоматичну вибірку затримано або призупинено." },
            { "WzSafeTitle1", "Координатно-копіювальний ключ" },
            { "WzSafeDesc1", "MiniMap запитує координати за допомогою вбудованої команди SCUM Copy location і зчитує їх із буфера обміну." },
            { "WzSafeTitle2", "Чат відкрито: автоматичне копіювання призупинено." },
            { "WzSafeDesc2", "Копіювання координат призупиняється, поки активний чат або виявлений вхід інвентарю, а також коли SCUM втрачає фокус." },
            { "WzSafeTitle3", "Майстер перезв’язування ключів SCUM" },
            { "WzSafeDesc3", "Зберігайте прив’язки до карт, чатів і копій у MiniMap у відповідності з вашими налаштуваннями SCUM." },
